/**
 * Return one page of the GitHub repositories whose events reach the caller's goals, oldest first. Never a webhook secret. A missing cursor starts at the first page and nextCursor null ends the list.
 * @summary List GitHub event sources
 */

export const ListGithubEventSourcesParams = zod.object({
  organizationId: zod
    .string()
    .min(1)
    .describe(
      "The organization, by its id or its slug. One the caller is not a member of answers as one that does not exist, `default` included.",
    ),
});

export const listGithubEventSourcesQueryLimitDefault = 50;
export const listGithubEventSourcesQueryLimitMax = 100;

export const listGithubEventSourcesQueryCursorMax = 4096;

export const listGithubEventSourcesQueryCursorRegExp = new RegExp(
  "^[A-Za-z0-9_-]+$",
);

export const ListGithubEventSourcesQueryParams = zod.object({
  limit: zod
    .int()
    .min(1)
    .max(listGithubEventSourcesQueryLimitMax)
    .default(listGithubEventSourcesQueryLimitDefault)
    .describe("Most items in one page."),
  cursor: zod
    .string()
    .min(1)
    .max(listGithubEventSourcesQueryCursorMax)
    .regex(listGithubEventSourcesQueryCursorRegExp)
    .optional()
    .describe(
      "Opaque continuation from the previous page's nextCursor, bound to the organization and the filters that made it. The server only ever issues cursors written in URL-safe base64 (letters, digits, - and _, no padding) and refuses anything else, so the pattern says so. A cursor that fits the pattern can still be refused: one this list never gave out, or one made for another organization or other filters.",
    ),
});

export const listGithubEventSourcesResponseNextCursorMax = 4096;

export const listGithubEventSourcesResponseNextCursorRegExp = new RegExp(
  "^[A-Za-z0-9_-]+$",
);

export const ListGithubEventSourcesResponse = zod.object({
  githubEventSources: zod
    .array(
      zod
        .object({
          id: zod.string().describe("The source's id."),
          source: zod.literal("github"),
          repository: zod.string().describe("The repository, as owner/name."),
          createdAt: zod.iso
            .datetime({ offset: true })
            .describe("When it was connected."),
          webhookPath: zod
            .string()
            .describe(
              "The path on this server to give the repository's webhook, with the source's secret. A client shows it on this server's own address and never builds it.",
            ),
        })
        .describe(
          "A GitHub repository whose webhook reaches the person's goals. Never its secret.",
        ),
    )
    .describe("Oldest first."),
  nextCursor: zod
    .string()
    .max(listGithubEventSourcesResponseNextCursorMax)
    .regex(listGithubEventSourcesResponseNextCursorRegExp)
    .nullable()
    .describe(
      "Pass as cursor for the next page. Null ends the list. Written in URL-safe base64, the only form the cursor parameter accepts.",
    ),
});

